export const TARGET_STARTS={snow:{id:'snow-start',name:'Schneeballplatz · Hüte treffen',region:'village',x:1,z:15,range:2.3,targetGame:'snow'},birds:{id:'birds-start',name:'Vogelchallenge im Arvenwald',region:'wald',x:13,z:1,range:2.3,targetGame:'birds'}};
export const TARGET_NAMES={snow:'Schneeballplatz · Hüte treffen',birds:'Vogelchallenge im Arvenwald'};
export const TARGET_LEVELS={easy:{name:'Gemütlich',speed:.7,time:40,ammo:16,goal:6,people:1,reward:1000},normal:{name:'Klassisch',speed:1,time:35,ammo:14,goal:7,people:2,reward:1800},hard:{name:'Knifflig',speed:1.35,time:30,ammo:14,goal:8,people:3,reward:2500}};
const keys=Object.keys(TARGET_LEVELS),entry=()=>({completed:[],best:{},runs:{easy:0,normal:0,hard:0}});
export const freshTargets=()=>({snow:entry(),birds:entry(),active:null});
export function atTargetStart(s,kind){const p=TARGET_STARTS[kind];return !!p&&s.position.region===p.region&&!s.position.inside&&!s.climbing.checkpoint&&!s.ski.active&&Math.hypot(s.position.x-p.x,s.position.z-p.z)<2.8;}
export function startTarget(s,kind,level){if(!Object.hasOwn(TARGET_STARTS,kind)||!keys.includes(level)||s.targets.active||!atTargetStart(s,kind))return{ok:false,message:'Gehe zuerst zum passenden Challenge-Platz.'};if(s.energy<5)return{ok:false,message:'Du brauchst 5 Energie. Raste oder iss etwas.'};s.energy-=5;s.targets.active={kind,level,time:0,countdown:3,ammo:TARGET_LEVELS[level].ammo,hits:0,misses:0,fouls:0,score:0,cooldown:0,ready:[0,0,0,0],aim:{x:0,y:6},done:false,reason:null};return{ok:true};}
export function targetObjects(c){const d=TARGET_LEVELS[c.level],t=c.time*d.speed,objects=[];if(c.kind==='snow'){
 for(let i=0;i<4;i++){const x=[-7,-2.4,2.4,7][i]+Math.sin(t*.65+i)*.35,y=5.6+Math.sin(t*.8+i)*.18;objects.push({id:'hat'+i,kind:'target',slot:i,x,y,z:0,visible:c.ready[i]<=c.time});}
 const period=7/d.speed,phase=c.time%period;if(phase>2.5&&phase<period-.8){const i=Math.floor(c.time/period)%4,o=objects[i];objects.push({id:'cover',kind:'cover',x:o.x,y:o.y,z:1.4,visible:true});}
 for(let i=0;i<d.people;i++)objects.push({id:'person'+i,kind:'protected',x:Math.sin(t*.5+i*2.2)*9,y:3.6,z:3+i*.05,visible:true});
 }else{for(let i=0;i<4;i++){const x=Math.sin(t*(.32+i*.025)+i*1.6)*8.3,y=7.2+Math.sin(t*.6+i*2)*1.7;objects.push({id:(i===3?'white':'bird')+i,kind:i===3?'protected':'target',slot:i,x,y,z:i===3?2:0,visible:c.ready[i]<=c.time});}}
 return objects;}

function endIfNeeded(c){const d=TARGET_LEVELS[c.level];if(c.fouls>=3){c.done=true;c.reason='protected';}else if(c.ammo<=0){c.done=true;c.reason='ammo';}else if(c.time>=d.time){c.done=true;c.reason='time';}}
export function stepTarget(c,dt){if(!c||c.done||!Number.isFinite(dt)||dt<0||dt>.1)return null;if(c.countdown>0){c.countdown=Math.max(0,c.countdown-dt);return null;}c.time=Math.min(TARGET_LEVELS[c.level].time,c.time+dt);c.cooldown=Math.max(0,c.cooldown-dt);endIfNeeded(c);return c.done?{type:'finish'}:null;}
export function shootTarget(c,id){if(!c||c.done||c.countdown>0||c.cooldown>0)return{ok:false,message:'Warte, bis du wieder bereit bist.'};const list=targetObjects(c),o=list.find(o=>o.id===id&&o.visible);c.ammo--;c.cooldown=.35;let type='miss';if(o?.kind==='protected'){c.fouls++;c.score-=20;type='protected';}else if(o?.kind==='target'){
 const cover=list.find(a=>a.kind==='cover'&&Math.abs(a.x-o.x)<.1);if(!cover){c.hits++;c.score+=10;c.ready[o.slot]=c.time+2.3/TARGET_LEVELS[c.level].speed;type='hit';}else{c.misses++;c.score-=5;type='cover';}
 }else{c.misses++;c.score-=5;if(o?.kind==='cover')type='cover';}endIfNeeded(c);return{ok:true,type,message:type==='hit'?'Treffer · +10 Punkte':type==='protected'?'Geschütztes Ziel · −20 Punkte · '+c.fouls+' / 3':type==='cover'?'Holzschirm · −5 Punkte':'Daneben · −5 Punkte'};}
export function finishTarget(s,exchange){const c=s.targets.active;if(!c?.done)return{ok:false,message:'Die Runde läuft noch.'};const d=TARGET_LEVELS[c.level],book=s.targets[c.kind],won=c.hits>=d.goal&&c.fouls<3,first=won&&!book.completed.includes(c.level),reward=first?d.reward:0;const r=exchange(s,{earn:reward,stats:{earned:reward},reason:'challenge',ref:c.kind+'-'+c.level});if(!r.ok)return r;book.best[c.level]=Math.max(book.best[c.level]??-1000,c.score);book.runs[c.level]=Math.min(1000000,book.runs[c.level]+1);if(first)book.completed.push(c.level);s.targets.active=null;return{ok:true,kind:c.kind,level:c.level,won,reward,score:c.score,hits:c.hits,misses:c.misses,fouls:c.fouls,time:c.time,reason:c.reason};}
export function validTargets(v,s){const obj=o=>o&&typeof o==='object'&&!Array.isArray(o),num=(x,a,b)=>Number.isFinite(x)&&x>=a&&x<=b,int=(x,a,b)=>Number.isSafeInteger(x)&&x>=a&&x<=b;if(!obj(v))return false;for(const k of Object.keys(TARGET_STARTS)){const b=v[k];if(!obj(b)||!Array.isArray(b.completed)||new Set(b.completed).size!==b.completed.length||!b.completed.every(k=>keys.includes(k))||!obj(b.best)||!Object.entries(b.best).every(([k,x])=>keys.includes(k)&&int(x,-1000,160))||!obj(b.runs)||Object.keys(b.runs).length!==3||!keys.every(k=>int(b.runs[k],0,1000000))||!b.completed.every(k=>b.runs[k]>0&&Object.hasOwn(b.best,k)))return false;}if(v.active===null)return true;const c=v.active,d=TARGET_LEVELS[c?.level];if(!obj(c)||!d||!Object.hasOwn(TARGET_STARTS,c.kind)||!atTargetStart(s,c.kind)||!num(c.time,0,d.time)||!num(c.countdown,0,3)||!num(c.cooldown,0,.35)||!int(c.ammo,0,d.ammo)||!int(c.hits,0,d.ammo)||!int(c.misses,0,d.ammo)||!int(c.fouls,0,3)||c.ammo+c.hits+c.misses+c.fouls!==d.ammo||c.score!==c.hits*10-c.misses*5-c.fouls*20||!Array.isArray(c.ready)||c.ready.length!==4||!c.ready.every(x=>num(x,0,d.time+4))||!obj(c.aim)||!num(c.aim.x,-10,10)||!num(c.aim.y,1,12)||typeof c.done!=='boolean'||!['protected','ammo','time',null].includes(c.reason)||c.done!==(c.fouls>=3||c.ammo===0||c.time>=d.time)||!c.done&&c.reason!==null||c.done&&c.reason==null||c.reason==='protected'&&c.fouls!==3||c.reason==='ammo'&&c.ammo!==0||c.reason==='time'&&c.time!==d.time||c.countdown>0&&(c.time!==0||c.ammo!==d.ammo||c.cooldown!==0))return false;return true;}
